  '{n} pièces gagnées': {'en': "{n} coins earned", 'es': "{n} monedas ganadas", 'pt': "{n} moedas ganhas", 'de': "{n} Münzen verdient", 'ar': "{n} عملة مكتسبة", 'zh': "已赚 {n} 金币", 'sw': "Sarafu {n} zimepatikana"},
  'Prix': {'en': "Price", 'es': "Precio", 'pt': "Preço", 'de': "Preis", 'ar': "السعر", 'zh': "价格", 'sw': "Bei"},
  'Ce modèle utilise les filtres de visage, disponibles sur Android pour le moment.': {'en': "This template uses face filters, available on Android for now.", 'es': "Esta plantilla usa filtros de rostro, disponibles por ahora en Android.", 'pt': "Este modelo usa filtros de rosto, disponíveis por agora no Android.", 'de': "Diese Vorlage nutzt Gesichtsfilter, derzeit nur auf Android verfügbar.", 'ar': "يستخدم هذا القالب فلاتر الوجه، وهي متاحة على أندرويد حاليًا.", 'zh': "此模板使用人脸滤镜，目前仅限 Android。", 'sw': "Kiolezo hiki hutumia vichujio vya uso, vinavyopatikana kwenye Android kwa sasa."},
  'Voici ton post tel qu\'il sera vu, avec tes widgets.': {'en': "Here is your post as it will be seen, with your widgets.", 'es': "Así se verá tu publicación, con tus widgets.", 'pt': "Assim será vista a tua publicação, com os teus widgets.", 'de': "So wird dein Beitrag aussehen, mit deinen Widgets.", 'ar': "هكذا سيظهر منشورك مع ودجاتك.", 'zh': "这是你的帖子发布后的样子，包含你的小组件。", 'sw': "Hivi ndivyo chapisho lako litakavyoonekana, pamoja na wijeti zako."},
  'Préparation des images…': {'en': "Preparing the images…", 'es': "Preparando las imágenes…", 'pt': "A preparar as imagens…", 'de': "Bilder werden vorbereitet…", 'ar': "جارٍ تجهيز الصور…", 'zh': "正在准备图片…", 'sw': "Inaandaa picha…"},
  "Montage de l'histoire…": {'en': "Building the story…", 'es': "Montando la historia…", 'pt': "A montar a história…", 'de': "Geschichte wird zusammengestellt…", 'ar': "جارٍ تركيب القصة…", 'zh': "正在制作故事…", 'sw': "Inaunda hadithi…"},
  'Une vidéo qui défile toute seule : {n} scènes, {s} secondes. Change les photos et les phrases comme tu veux.': {'en': "A video that plays by itself: {n} scenes, {s} seconds. Change the photos and the sentences as you like.", 'es': "Un vídeo que avanza solo: {n} escenas, {s} segundos. Cambia las fotos y las frases como quieras.", 'pt': "Um vídeo que avança sozinho: {n} cenas, {s} segundos. Muda as fotos e as frases como quiseres.", 'de': "Ein Video, das von selbst abläuft: {n} Szenen, {s} Sekunden. Ändere Fotos und Sätze, wie du möchtest.", 'ar': "فيديو يتقدم وحده: {n} مشاهد، {s} ثانية. غيّر الصور والجمل كما تشاء.", 'zh': "自动播放的视频：{n} 个场景，{s} 秒。照片和文字都可以随意修改。", 'sw': "Video inayojiendesha yenyewe: matukio {n}, sekunde {s}. Badilisha picha na sentensi upendavyo."},
  'Phrase de la scène {n}': {'en': "Sentence of scene {n}", 'es': "Frase de la escena {n}", 'pt': "Frase da cena {n}", 'de': "Satz der Szene {n}", 'ar': "جملة المشهد {n}", 'zh': "场景 {n} 的文字", 'sw': "Sentensi ya tukio {n}"},
  'Tes photos ({n}/5)': {'en': "Your photos ({n}/5)", 'es': "Tus fotos ({n}/5)", 'pt': "As tuas fotos ({n}/5)", 'de': "Deine Fotos ({n}/5)", 'ar': "صورك ({n}/5)", 'zh': "你的照片（{n}/5）", 'sw': "Picha zako ({n}/5)"},
  'Sans photo, les scènes sont sur fond uni. Les photos passent à tour de rôle.': {'en': "Without photos, the scenes use a plain background. Photos take turns.", 'es': "Sin fotos, las escenas llevan un fondo liso. Las fotos se turnan.", 'pt': "Sem fotos, as cenas ficam com fundo liso. As fotos alternam.", 'de': "Ohne Fotos haben die Szenen einen einfarbigen Hintergrund. Die Fotos wechseln sich ab.", 'ar': "بدون صور تكون المشاهد على خلفية سادة. تتناوب الصور.", 'zh': "没有照片时场景使用纯色背景。照片会轮流出现。", 'sw': "Bila picha, matukio yana mandharinyuma ya kawaida. Picha zinapokezana."},
  'Créer la vidéo 🎬': {'en': "Create the video 🎬", 'es': "Crear el vídeo 🎬", 'pt': "Criar o vídeo 🎬", 'de': "Video erstellen 🎬", 'ar': "إنشاء الفيديو 🎬", 'zh': "生成视频 🎬", 'sw': "Unda video 🎬"},
  'Choisis {n} photos, une par case. Tu peux changer les étiquettes et le titre.': {'en': "Pick {n} photos, one per slot. You can change the labels and the title.", 'es': "Elige {n} fotos, una por casilla. Puedes cambiar las etiquetas y el título.", 'pt': "Escolhe {n} fotos, uma por caixa. Podes mudar as etiquetas e o título.", 'de': "Wähle {n} Fotos, eine pro Feld. Du kannst Beschriftungen und Titel ändern.", 'ar': "اختر {n} صور، صورة لكل خانة. يمكنك تغيير التسميات والعنوان.", 'zh': "选择 {n} 张照片，每格一张。可以修改标签和标题。", 'sw': "Chagua picha {n}, moja kwa kila sehemu. Unaweza kubadilisha lebo na kichwa."},
  'Étiquette de la photo {n}': {'en': "Label of photo {n}", 'es': "Etiqueta de la foto {n}", 'pt': "Etiqueta da foto {n}", 'de': "Beschriftung von Foto {n}", 'ar': "تسمية الصورة {n}", 'zh': "照片 {n} 的标签", 'sw': "Lebo ya picha {n}"},
