  'Rechercher une musique': {'en': "Search a track", 'es': "Buscar una música", 'pt': "Procurar uma música", 'de': "Musik suchen", 'ar': "ابحث عن موسيقى", 'zh': "搜索音乐", 'sw': "Tafuta muziki"},
  'Aucune musique ne correspond.': {'en': "No track matches.", 'es': "Ninguna música coincide.", 'pt': "Nenhuma música corresponde.", 'de': "Keine Musik passt.", 'ar': "لا توجد موسيقى مطابقة.", 'zh': "没有匹配的音乐。", 'sw': "Hakuna muziki inayolingana."},
